'use strict';

/**
* Serializes an unsigned 64-bit integer as a JSON object.
*
* @private
* @returns {Object} JSON representation
*/
function toJSON() {
	var out = {};
	out.type = 'Uint64';
	if ( typeof this.value === 'bigint' ) {
		out.value = this.value.toString();
	}
	else {
		out.value = [ this.value[ 0 ], this.value[ 1 ] ];
	}
	return out;
}


// EXPORTS //

module.exports = toJSON;
